  ro_cells asegs m c [C8 (wz AVP_CONFIG_SVC)] -> ro_cells asegs m (c + O_CFG_HINT) [C4 (wz 4294967295)] ->
  aapp c SZ_CFG -> fsobj H LF c SZ_CFG -> accessible m c SZ_CFG -> c mod 16 = 0 ->
  AXStatics2 m ->
  rw_cells asegs m (bv_unsigned tp + -164) [C4 errv] -> tp = Z_to_bv 64 ATP ->
  bv_unsigned sp mod 16 = 0 ->
  stk asegs m lo (bv_unsigned sp) -> lo + ACONFIG_GET_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m ->
  ACONST m -> athr_cells m -> as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> acanary m ->
  (forall (m2 : mem) (spa : Z) (pad : list cell) (w0 : word) (h32 j216 shb : list byte) (ff fp : Z)
          (rax t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word),
     rw_cells asegs m2 spa pad -> Z.of_nat (cells_size pad) = bv_unsigned sp + -96 - spa ->
     lo + AGET_VALUE_STACK <= spa -> spa + 96 <= bv_unsigned sp -> spa mod 32 = 0 ->
     rw_cells asegs m2 (bv_unsigned sp + -96) (cg_frame w0 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
     rw_cells asegs m2 ff [CB 32 h32; CB 216 j216; C8 (Z_to_bv 64 fp)] ->
     rw_cells asegs m2 (Z.shiftr ff 3 + 2147450880) [CB 8 cg_shhead; CB 24 shb] ->
     rw_cells asegs m2 fp [C1 (b8 1)] ->
     stk asegs m2 lo spa -> mem_inv asegs m2 ->
     as_RFS H ((2, ff, fp) :: LF) m2 -> fresh_frame H LF 2 ff fp -> ACONST m2 -> stack0 m2 lo shi ->
     munch (cg_W H lo sp ff fp) m m2 -> wmono asegs m m2 ->
     ro_cells asegs m2 c [C8 (wz AVP_CONFIG_SVC)] -> ro_cells asegs m2 (c + O_CFG_HINT) [C4 (wz 4294967295)] ->
     accessible m2 c SZ_CFG ->
     (c + SZ_CFG <= ff \/ ff + ACG_FSZ <= c) -> (c + SZ_CFG <= fp \/ fp + 1 <= c) ->
     AXStatics2 m2 -> rw_cells asegs m2 (bv_unsigned tp + -164) [C4 errv] -> acanary m2 ->
     evt asegs Q
       (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
                (Z_to_bv 64 ff) dflt (Z_to_bv 64 (akey_lit k)) (Z_to_bv 64 AL_STR_SCHEDULER) (Z_to_bv 64 c)
                (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s10 s11 t3' t4' t5' t6')
           F (Z_to_bv 64 pch) fc None m2 (seg_rom asegs))) ->
  evt asegs Q
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz c) (wz AL_STR_SCHEDULER) (wz (akey_lit k)) dflt (wz 0) a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m (seg_rom asegs)).
